// Detects suspicious file download using curl.exe
// This could be an attacker downloading tools, or second stage malware execution.
let ProcessNames = dynamic(["curl.exe"]);
let cmd_all = dynamic(["http"]);
let cmd_any = dynamic(["-o","--remote-name","--output"]);
_Im_ProcessCreate(targetprocess_has_any=ProcessNames,commandline_has_all=cmd_all,commandline_has_any=cmd_any)
| extend split(CommandLine, "curl.exe")
| where CommandLine has_any (".bat",".dat",".dll",".exe",".gif",".hta",".jpeg",".log",".msi",".png",".ps1",".psm1",".vbe",".vbs")
| extend
    Account = tostring(column_ifexists("ActorUsername", "")),
    AccountDomain = tostring(column_ifexists("ActorUserDomain", "")),
    Computer = tostring(column_ifexists("DvcHostname", "")),
    ProcessName = tostring(column_ifexists("TargetProcessName", "")),
    ProcessId = tostring(column_ifexists("TargetProcessId", "")),
    CommandLine = tostring(column_ifexists("CommandLine", ""))
| where isnotempty(ProcessName)
